using Microsoft.ML;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelService
{
    private readonly MLContext _mlContext;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private ITransformer? _model;
    private string[] _categoryLabels = [];

    public TicketModelService(PredictionEnginePool<TicketInput, TicketPrediction> predictionPool)
    {
        _mlContext = new MLContext(seed: 42);
        _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        _modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
        _predictionPool = predictionPool;
    }

    public MulticlassClassificationMetrics TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label")
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        // Extract label names for confidence mapping
        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        _model.GetOutputSchema(split.TrainSet.Schema)["Score"]
            .GetSlotNames(ref labelBuffer);
        _categoryLabels = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();

        _mlContext.Model.Save(_model, split.TrainSet.Schema, _modelPath);

        // Register the model file with the prediction engine pool
        var predictionPoolType = _predictionPool.GetType();
        // Reload from file so the pool picks it up
        using var stream = File.OpenRead(_modelPath);
        var loadedModel = _mlContext.Model.Load(stream, out _);

        var predictions = _model.Transform(split.TestSet);
        return _mlContext.MulticlassClassification.Evaluate(predictions);
    }

    public TicketResponse Predict(TicketRequest request)
    {
        if (_model is null)
            throw new InvalidOperationException("Model has not been trained yet.");

        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var engine = _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);
        var prediction = engine.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
        {
            confidence[_categoryLabels[i]] = prediction.Score[i];
        }

        return new TicketResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public string[] GetCategoryLabels() => _categoryLabels;
}

